  function buildExamples(chunk, primaryExample) {
    const clean = chunk
      .replace(/\bdoing something\b/i, 'working on this')
      .replace(/\bfor something\b/i, 'for my priorities')
      .replace(/\bsomething off\b/i, 'it off')
      .replace(/\bsomething\b/i, 'it')
      .replace(/\bsomeone\b/i, 'them');
    return [
      { en: primaryExample || ('I try to ' + clean + ' every day.'), tag: 'Ngữ cảnh đời thường' },
      { en: 'In daily life, it really helps when you can ' + clean + ' naturally.', tag: 'Giao tiếp thực tế (US)' },
      { en: 'To be honest, I now ' + clean + ' whenever I have the chance.', tag: 'Phản xạ kể chuyện' }
    ];
  }

